N \'793000\' AND \'794999\' THEN \'Meghalaya\' WHEN PIN_code LIKE \'795%\' THEN \'Manipur\' WHEN PIN_code LIKE \'796%\' THEN \'Mizoram\' WHEN PIN_code BETWEEN \'797000\' AND \'798999\' THEN \'Nagaland\' WHEN PIN_code LIKE \'799%\' THEN \'Tripura\' WHEN PIN_code BETWEEN \'800000\' AND \'859999\' THEN \'Bihar, Jharkhand\' WHEN PIN_code BETWEEN \'900000\' AND \'999999\' THEN \'Army Postal Service\' ELSE \'Unknown\' END AS final_State, FROM ( select awb as awb_number ,TRY_TO_TIMESTAMP(\"Created at\", \'YYYY-MM-DD HH24:MI:SS\') as assigned_date ,TRY_TO_TIMESTAMP(\"Order Date\", \'YYYY-MM-DD HH24:MI:SS\') as ORDER_DATE_dummy ,\"Pickup Date\" ,TRY_TO_TIMESTAMP(\"Pickup Date\", \'YYYY-MM-DD HH24:MI:SS\') as PICKUP_DATE ,TRY_TO_TIMESTAMP(\"Delivery Date\", \'YYYY-MM-DD HH24:MI:SS\') as DELIVERY_DATE ,\"Current Location\" as Current_Location ,TRY_TO_TIMESTAMP(\"Latest Timestamp\", \'YYYY-MM-DD HH24:MI:SS\') as LATEST_TIMESTAMP ,\"Latest Remark\" as Latest_Remark ,\"Clickpost Unified Status\" as pre_current_status ,case when lower(pre_current_status) in (\'rto-shipmentdelay\',\'rto-delivered\',\'rto-intransit\',\'rto-requested\',\'rto-marked\',\'rto-contactcustomercare\',\'rto-outfordelivery\',\'rto-failed\') then \'RTO\' when lower(pre_current_status) in (\'pickedup\',\'destinationhubin\',\'contactcustomercare\',\'shipmentdelayed\',\'origincityin\',\'outfordelivery\',\'intransit\',\'origincityout\',\'shipmentheld\') then \'INTRANSIT\' when lower(pre_current_status) in (\'delivered\') then \'DELIVERED\' when lower(pre_current_status) in (\'cancelled\') then \'CANCELLED\' when lower(pre_current_status) in (\'orderplaced\',\'outforpickup\',\'awb registered\',\'pickuppending\',\'pickupfailed\') then \'ORDER_PLACED\' when lower(pre_current_status) in (\'faileddelivery\',\'notserviceable\') then \'UNDELIVERED\' when lower(pre_current_status) in (\'lost\',\'damaged\') then \'LOST\' END as status ,\"Order ID\" as ORDER_ID ,\"Product SKU Code\" SKU_LIST ,\"Items Quantity\" quantity_in